/**
 * Банк предметов RGG Land (сезон Осень 2026, fall26): название -> { тип, описание }.
 * Источник: https://rgg.land/items (RSC-поток Next.js), поле "items" у "L4a".
 * Тип = префикс описания до точки («Оружие. », «Зелье. » и т.д.).
 */

/** Все типы предметов RGG Land (в естественном порядке банка). */
