/**
 * Ищет предмет в банке, устойчивый к суффиксам количества (×N).
 * Сначала точное имя, затем — усечение « ×N»/« xN» в конце. null — не найдено.
 */
export function lookupBankItem(name: string): RggItemBankEntry | null {
	const clean = name.trim();
	const direct = RGG_ITEM_BANK[clean];
	if (direct) {
		return direct;
	}
	const withoutCount = clean.replace(/\s+[х×xX]\s*\d+\s*$/u, '');
	if (withoutCount && withoutCount !== clean) {
		return RGG_ITEM_BANK[withoutCount] ?? null;
	}
	return null;
}
